style.css:
@-moz-document domain("centralgraphics-cg.com") {
/* Fondo general */
  body, #contenedor, #TB_window, #scan_contenido, #finalizar_sap, #reportar_material, #fecha-trabajo {
    background-color: #212121 !important;
    color: #ffffff !important;
  }

  /* Textos generales */
  body, td, th, .msj_usuario, #nombre_usuario, input, textarea, select {
    color: #ffffff !important;
  }

  /* Fondos y bordes de inputs */
  input, textarea, select {
    background-color: #2c2c2c !important;
    border-color: #555 !important;
  }

  input:focus, textarea:focus, select:focus {
    border-color: #80b3ff !important;
  }

  /* Botones */
  input[type="submit"], input[type="button"] {
    background-color: #3c3c3c !important;
    color: #e0e0e0 !important;
    border-color: #666 !important;
    text-shadow: none !important;
  }

  input[type="submit"]:hover, input[type="button"]:hover {
    background-color: #555 !important;
    color: #ffffff !important;
  }

  /* Tooltips (Ventas, Plani, etc.) */
  .toolizq span, .toolder span {
    background-color: #ff6f00 !important;
    color: #ffffff !important;
    border-color: #80b3ff !important;
    text-shadow: none !important;
  }

  /* Encabezado y navegación */
  .encabezado {
    background-color: #444 !important;
    color: #ffffff !important;
    border-bottom-color: #666 !important;
  }

  #navegacion a, #navegacion ul li a {
    color: #ffe082 !important;
  }

  #navegacion li:hover {
    background-color: #555 !important;
  }

  #navegacion li:hover > a {
    color: #ffca28 !important;
  }

  /* Tablas */
  .tabular th {
    background-color: #555 !important;
    color: #ffffff !important;
  }

  .tabular tr:hover {
    background-color: #3a3a3a !important;
  }

  /* Créditos */
  .credito {
    background-color: #1a1a1a !important;
    color: #cccccc !important;
    border-top: 1px solid #333 !important;
  }

  /* Caja amarilla */
  .caja_amarilla {
    background-color: #7a5c00 !important;
    color: #ffffff !important;
  }

  /* Estados de ruta */
  .rut_Agregado {
    background-color: #cc9a74 !important;
  }

  .rut_Asignado, .rut_Procesando, .rut_Pausado {
    background-color: #fa9e57 !important;
  }

  .rut_Aprobacion {
    background-color: #d49b1e !important;
  }

  .rut_Terminado {
    background-color: #ff6f00 !important;
  }

  /* jQuery UI Tabs */
  #tabs, #tabs .ui-widget-content, #tabs .ui-widget-header {
    background-color: #2d2d2d !important;
    border-color: #666 !important;
  }

  /* Tooltip gráfico de barras */
  #gbarras_tool {
    background-color: #222 !important;
    color: #ffffff !important;
    box-shadow: 0 0 8px #ffffff !important;
  }

  /* Links */
  a {
    color: #EDBE60 !important;
  }

  /* Iconos de menú */
  [class*=MID_] span {
    background: url('https://i.postimg.cc/fRyrrBDb/menu-icons.png') !important;
  }
  
.sombra{
	-moz-box-shadow:    rgba(115.8, 115.8, 115.8, 1);
	-webkit-box-shadow: rgba(115.8, 115.8, 115.8, 1);
	box-shadow:         rgba(115.8, 115.8, 115.8, 1);
}

/* Posiciones de iconos fuera de @-moz-document */
.MID_ventas span, .MID_ventas:hover span {
  background-position: 0px -256px;
}

.MID_materias span, .MID_materias:hover span {
  background-position: 0px -96px;
}

.MID_reporte span, .MID_reporte:hover span {
  background-position: 0px -64px;
}

.MID_trabajos span, .MID_trabajos:hover span {
  background-position: 0px 0px;
}

.MID_requisar span, .MID_requisar:hover span {
  background-position: 0px -96px;
}

.MID_clientes span, .MID_clientes:hover span {
  background-position: 0px -128px;
}

.MID_grupos span, .MID_grupos:hover span {
  background-position: 0px -192px;
}

.MID_tablero span, .MID_tablero:hover span {
  background-position: 0px -32px;
}

.MID_facturas span, .MID_facturas:hover span {
  background-position: 0px -64px;
}
}
